CREATE VIEW v35090 AS SELECT ADDTIME(x1.v34994, '00:00:00.000001'), ADDTIME(x1.v34993, '10:00:00.000001'), ADDTIME(CAST(x1.v34994 AS DATETIME(0)), 100000), ADDTIME(CAST(x1.v34994 AS DATETIME(0)), 100000.1), ADDTIME(CAST(x1.v34993 AS DATETIME(0)), CAST('10:00:00' AS TIME(0))), ADDTIME(CAST(x1.v34993 AS DATETIME(6)), CAST('10:00:00' AS TIME(0))), ADDTIME(CAST(x1.v34994 AS DATETIME(0)), CAST('10:00:00' AS TIME(6))) FROM v34992 AS x1